package com.studybuddy.api.domain;
import jakarta.persistence.*;
import java.time.Instant;
@Entity @Table(name="study_groups")
public class StudyGroup { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="course_id",nullable=false) private Course course; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="owner_id",nullable=false) private User owner; @Column(nullable=false,length=100) private String name; @Column(nullable=false,length=1000) private String description; @Column(nullable=false) private int capacity; @Column(name="study_mode",nullable=false,length=40) private String studyMode; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); protected StudyGroup(){} public StudyGroup(Course course,User owner,String name,String description,int capacity,String studyMode){this.course=course;this.owner=owner;this.name=name;this.description=description;this.capacity=capacity;this.studyMode=studyMode;} public Long getId(){return id;} public Course getCourse(){return course;} public User getOwner(){return owner;} public String getName(){return name;} public String getDescription(){return description;} public int getCapacity(){return capacity;} public String getStudyMode(){return studyMode;} }
